"""Read a bounded, local palette generated by Avra.nvim. No executable theme code."""

import hashlib
import json
import os
import re
import stat

from runtime import ROOT

KEYS = frozenset(
    ("bg", "surface", "text", "muted", "dim", "line", "warn", "error", "accent", "fill")
)


def read_palette(root=ROOT):
    try:
        fd = os.open(
            root / "appearance.json", os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK
        )
    except FileNotFoundError:
        return {}
    try:
        info = os.fstat(fd)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_size > 4096
        ):
            raise ValueError(
                "appearance.json must be an owned regular file <=4096 bytes"
            )
        with os.fdopen(fd, "rb", closefd=False) as file:
            data = json.loads(file.read(4097))
    finally:
        os.close(fd)
    if (
        not isinstance(data, dict)
        or set(data) != {"managed_by", "colors", "checksum"}
        or data["managed_by"] != "avra.nvim"
    ):
        raise ValueError("invalid appearance.json metadata")
    colors = data["colors"]
    if (
        not isinstance(colors, dict)
        or set(colors) != KEYS
        or any(
            not isinstance(c, str) or not re.fullmatch(r"#[0-9a-f]{6}", c)
            for c in colors.values()
        )
    ):
        raise ValueError("invalid appearance.json colors")
    body = "\n".join(key + "=" + colors[key] for key in sorted(KEYS))
    if data["checksum"] != hashlib.sha256(body.encode()).hexdigest():
        raise ValueError("appearance.json checksum mismatch")
    return {key: value[1:] for key, value in colors.items()}
